"""Validation API for the data-validation work sample."""

import math


def evaluate(request, policy):
    """Validate and normalize every row using the supplied policy."""
    accepted = []
    errors = []
    seen = set()

    for index, row in enumerate(request["rows"]):
        if hasattr(row, "get"):
            identifier = row.get("id")
            amount = row.get("amount")
            unit = row.get("unit", policy["base_unit"])
        else:
            identifier = None
            amount = None
            unit = policy["base_unit"]

        if not isinstance(identifier, str) or not identifier:
            cause = "id"
        elif (
            isinstance(amount, bool)
            or not isinstance(amount, (int, float))
            or (isinstance(amount, float) and not math.isfinite(amount))
            or amount < 0
        ):
            cause = "amount"
        else:
            try:
                valid_unit = unit in policy["units"]
            except (TypeError, ValueError):
                valid_unit = False

            if not valid_unit:
                cause = "unit"
            elif policy["unique"] and identifier in seen:
                cause = "duplicate"
            else:
                cause = None

        if cause is not None:
            errors.append({"row": index, "cause": cause})
            continue

        accepted.append({
            "id": identifier,
            "amount": amount * policy["units"][unit],
        })
        seen.add(identifier)

    if errors:
        return {"ok": False, "records": [], "errors": errors}
    return {"ok": True, "records": accepted, "errors": []}

